def build():
    reader.validate()
    OUT.mkdir(parents=True,exist_ok=True)
    (OUT/'assets').mkdir(exist_ok=True)
    for item in SEED.iterdir():shutil.copy2(item,OUT/'assets'/item.name)
    shutil.copytree(ROOT/'content/report-assets',OUT/'assets/report',dirs_exist_ok=True)
    (OUT/'assets/baselines').mkdir(exist_ok=True)
    shutil.copy2(ROOT/'docs/chapter-presentation-baseline-v1.md',OUT/'assets/baselines/chapter-presentation-baseline-v1.md')
    shutil.copy2(ROOT/'content/baselines/chapter-presentation-v1.json',OUT/'assets/baselines/chapter-presentation-v1.json')
    shutil.copy2(ROOT/'docs/goso-theme-map-baseline-v1.md',OUT/'assets/baselines/goso-theme-map-baseline-v1.md')
    shutil.copy2(ROOT/'content/baselines/goso-theme-map-v1.json',OUT/'assets/baselines/goso-theme-map-v1.json')
    shutil.copy2(ROOT/'content/baselines/current.json',OUT/'assets/baselines/current.json')
    shutil.copytree(ROOT/'content/reviews/cmap-2-2',OUT/'assets/reviews/cmap-2-2',dirs_exist_ok=True)
    shutil.copy2(ROOT/'docs/cmap-2-2-review-plan-20261015.md',OUT/'assets/reviews/cmap-2-2/plan.md')
    goso.export(OUT)
    __import__('amap_content').export(OUT)
    __import__('dmap_content').export(OUT)
    __import__('gmap_content').export(OUT)
    gosr.export(OUT)
    landscape.export(OUT)
    shutil.copy2(ROOT/'content/chart-data.js',OUT/'content.js')
    (OUT/'.nojekyll').write_text('')
    __import__('goso_brand').export(OUT)
    for src,dst in [('reading-experience.css','reading-experience.css'),('reading-experience.js','reading-experience.js'),('vmap.css','vmap.css'),('vmap.js','vmap.js'),('chapter1-slides.css','chapter1-slides.css'),('chapter1-explorers.css','chapter1-explorers.css'),('chapter1-explorers.js','chapter1-explorers.js'),('base.css','style.css'),('reader.css','reader.css'),('portal.css','portal.css'),('portal.js','portal.js'),('explore.js','explore.js'),('report.js','report.js'),('report.css','report.css'),('chapter-visuals.js','chapter-visuals.js'),('chapter-visuals.css','chapter-visuals.css'),('landscape.css','landscape.css'),('landscape.js','landscape.js'),('gosr.css','gosr.css'),('gosr.js','gosr.js'),('goso-reading.css','goso-reading.css'),('goso-reading.js','goso-reading.js'),('goso.css','goso.css'),('goso.js','goso.js'),('goso-atlas.css','goso-atlas.css'),('atlas-core.js','atlas-core.js'),('goso-atlas.js','goso-atlas.js'),('goso-editorial.js','goso-editorial.js'),('goso-brand.js','goso-brand.js'),('goso-editorial.css','goso-editorial.css')]:shutil.copy2(ROOT/'web'/src,OUT/dst)
    (OUT/'assets/gosd-mark.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="10" fill="#0a2c49"/><text x="32" y="41" text-anchor="middle" font-family="Arial,sans-serif" font-weight="bold" font-size="34" fill="#edf7fa">G</text><path d="M12 51h10" stroke="#279fa9" stroke-width="3"/><path d="M22 51h10" stroke="#4e87c5" stroke-width="3"/><path d="M32 51h10" stroke="#9973b7" stroke-width="3"/><path d="M42 51h10" stroke="#82ae53" stroke-width="3"/></svg>')
    for lang in ['zh','en']:
        t=lambda z,e:tr(lang,z,e)
        emit(lang,'','overview',t('全球开源发展报告','Global Open Source Development Report'),t('从普惠到质量，从参与到影响。','From inclusion to quality, from participation to impact.'),homepage(lang),is_home=True)
        emit(lang,'','report',t('报告全文','Read the report'),t('从目标到观测，从影响到行动。六章、30 个小节与三个附录，共同组织研究与证据。','From goals to observation, from impact to action. Six chapters, 30 sections and three appendices organize the research and evidence.'),reader.index_body(lang))
        for u in reader.UNITS:
            content=reader.body(u,lang).replace('/?lang='+lang+'#framework',path(lang,'data/goals/')).replace('/?lang='+lang+'#chapter-2',path(lang,'data/explore/'))
            active='data' if u['kind']=='methods' else 'release' if u['kind']=='downloads' else 'report'
            if u['kind']=='downloads':content=releases(lang,True)
